SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, (COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) - 1) / NULLIF(COUNT(p.subject_id), 0) * (COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) - COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END)) AS ci, MEDIAN(CASE WHEN i.intime BETWEEN 0 AND 3 THEN i.los END), MEDIAN(CASE WHEN i.intime BETWEEN 4 AND 7 THEN i.los END), MEDIAN(CASE WHEN i.intime >= 8 THEN i.los END) AS median_los FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 80 AND 90 AND a.admission_type_id = 757071;